<?php
declare(strict_types=1);
namespace App\Application\QuestionLearning\Service;
use App\Application\QuestionLearning\DTO\Request\RequestQuestionExplanationRequestDto;use App\Application\QuestionLearning\DTO\Response\QuestionExplanationResponseDto;use App\Application\QuestionLearning\Mapper\QuestionExplanationResponseMapper;use App\Domain\Performance\Repository\AttemptRepositoryInterface;use App\Domain\QuestionBank\Repository\FrozenQuestionReaderInterface;use App\Domain\QuestionLearning\Entity\QuestionExplanationExecution;use App\Domain\QuestionLearning\Enum\ExplanationStatus;use App\Domain\QuestionLearning\Repository\QuestionExplanationExecutionRepositoryInterface;use App\Domain\QuestionLearning\Service\QuestionExplanationSafetyPolicy;
final readonly class RequestQuestionExplanationService { public function __construct(private FrozenQuestionReaderInterface $questions,private AttemptRepositoryInterface $attempts,private QuestionExplanationExecutionRepositoryInterface $executions,private QuestionExplanationSafetyPolicy $policy,private QuestionExplanationResponseMapper $mapper) {} public function execute(string $userId,RequestQuestionExplanationRequestDto $request,\DateTimeImmutable $now):QuestionExplanationResponseDto { if(count($this->questions->findByIds([$request->questionId]))!==1)throw new \DomainException('Questão não encontrada.');$completed=null;if($request->attemptId!==null){$attempt=$this->attempts->findByIdForUser($request->attemptId,$userId);if($attempt===null||$attempt->questionId!==$request->questionId)throw new \DomainException('Tentativa não encontrada.');$completed=$attempt->completedAt!==null;}$version='question-explanation-v1';$existing=$this->executions->findByRequest($userId,$request->questionId,$request->attemptId,$version);if($existing!==null)return $this->mapper->toResponse($existing);$execution=new QuestionExplanationExecution($this->uuid(),$userId,$request->questionId,$request->attemptId,$version,$this->policy->mode($completed),ExplanationStatus::PENDING,0,null,null,null,null,null,null,null,$now);$this->executions->save($execution);return $this->mapper->toResponse($execution);}private function uuid():string{$b=random_bytes(16);$b[6]=chr((ord($b[6])&15)|64);$b[8]=chr((ord($b[8])&63)|128);return vsprintf('%s%s-%s-%s-%s-%s%s%s',str_split(bin2hex($b),4));}}
